solution.code:
function roleLabel(role) {
  switch (role) {
    case 'admin': return 'Administrator';
    case 'editor': return 'Editor';
    case 'viewer': return 'Viewer';
    default: return 'Unknown';
  }
}

console.log(roleLabel('admin')); // 'Administrator'

function categorize(n) {
  if (typeof n !== 'number' || Number.isNaN(n)) return 'invalid';
  if (n < 0) return 'negative';
  if (n === 0) return 'zero';
  return 'positive';
}

console.log(categorize(-5));   // 'negative'
console.log(categorize(0));    // 'zero'
console.log(categorize(42));   // 'positive'
console.log(categorize('x'));  // 'invalid'
console.log(categorize(NaN));  // 'invalid'
